-- PHB v3.5 starter Wizard spell definitions needed by character creation.
-- These fill level-1 creator gaps in the current batched PHB spell catalog.
-- Safe to re-run.
INSERT OR IGNORE INTO dnd35_spells
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) VALUES
  ('phb-spell-burning-hands','phb-3.5','207','burning-hands','Burning Hands','A short cone of flame burns creatures and ignites exposed flammable material.','Deals 1d4 fire damage per caster level, maximum 5d4, in a 15-foot cone. A successful Reflex save halves the damage.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action','standard','15 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Reflex half','ref','yes','Yes'),
  ('phb-spell-charm-person','phb-3.5','209','charm-person','Charm Person','A humanoid that fails its save regards the caster as a trusted friend and ally for the duration.','Affects one humanoid. The target receives a Will save; threatening circumstances can improve that save, and threatening the charmed creature can end the effect.',0,NULL,1,'phb-spell-school-enchantment','Charm','1 standard action','standard','Close (25 ft. + 5 ft./2 levels)','One humanoid creature',NULL,NULL,'1 hour/level','Will negates','will','yes','Yes'),
  ('phb-spell-mage-armor','phb-3.5','249','mage-armor','Mage Armor','A tangible force field protects the touched creature.','Grants a +4 armor bonus to Armor Class for 1 hour per caster level. Because it is a force effect, it also protects against incorporeal touch attacks.',0,NULL,1,'phb-spell-school-conjuration','Creation','1 standard action','standard','Touch','Creature touched',NULL,NULL,'1 hour/level (D)','Will negates (harmless)','will','no','No'),
  ('phb-spell-magic-missile','phb-3.5','251','magic-missile','Magic Missile','Unerring missiles of force strike designated creatures within range.','Each missile deals 1d4+1 force damage. The caster gains one additional missile every two caster levels beyond 1st, to a maximum of five missiles at caster level 9.',0,NULL,1,'phb-spell-school-evocation',NULL,'1 standard action','standard','Medium (100 ft. + 10 ft./level)','Up to five creatures, no two more than 15 ft. apart',NULL,NULL,'Instantaneous','None',NULL,'yes','Yes');
